import { test, expect, Page } from '@playwright/test';
import { readFileSync } from 'node:fs';

// Search engines (1.11.2026): hreflang and canonical on the home page and the games, a sitemap with each language at its
// own address, and no ski resort in testing (?resort=) anywhere. Generated by tools/build-games.py and tools/build-sitemap.py.
const SITE = 'https://gudauri-ski-trip.vercel.app';
const LANGS = ['he', 'en', 'ru', 'ka'];
const PAGES = ['/', '/games/descent/', '/games/school/', '/games/fresh-snow/', '/games/snowball/', '/games/merge/'];
const sitemap = readFileSync('site/sitemap.xml', 'utf8');
const locs = [...sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1]);

async function head(page: Page) {
  return page.evaluate(() => ({
    canonical: [...document.querySelectorAll('link[rel="canonical"]')].map(l => (l as HTMLLinkElement).href),
    alternates: Object.fromEntries([...document.querySelectorAll('link[rel="alternate"][hreflang]')].map(l => [l.getAttribute('hreflang'), (l as HTMLLinkElement).href])),
  }));
}

test('sitemap.xml: כל שפה בכתובת משלה, בלי ?resort=, ותואם לכלי', () => {
  expect(sitemap).not.toContain('resort');
  for (const p of PAGES) {
    expect(locs, p).toContain(SITE + p);
    for (const l of LANGS) expect(locs, `${p} ${l}`).toContain(`${SITE}${p}?lang=${l}`);
    // every address of the page lists all five alternates (four languages and the x-default)
    for (const u of [SITE + p, ...LANGS.map(l => `${SITE}${p}?lang=${l}`)]) {
      const entry = sitemap.split('<url>').find(e => e.startsWith(`<loc>${u}</loc>`))!;
      expect(entry, u).toBeTruthy();
      expect((entry.match(/hreflang=/g) || []).length).toBe(5);
      expect(entry).toContain(`hreflang="x-default" href="${SITE}${p}"`);
    }
  }
  expect(sitemap).toContain('xmlns:xhtml="http://www.w3.org/1999/xhtml"');
  // the language of the privacy and support pages is the #hash, which search engines do not see: one address each
  for (const p of ['/privacy', '/support']) expect(locs.filter(u => u === SITE + p)).toHaveLength(1);
  expect(new Set(locs).size).toBe(locs.length);
});

for (const p of PAGES) {
  test(`hreflang ו-canonical ב-${p}`, async ({ page }) => {
    const errors: string[] = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto(p);
    let h = await head(page);
    // the plain address: its own canonical, the x-default, and every language at ?lang=
    expect(h.canonical).toEqual([SITE + p]);
    expect(h.alternates['x-default']).toBe(SITE + p);
    for (const l of LANGS) expect(h.alternates[l]).toBe(`${SITE}${p}?lang=${l}`);
    expect(Object.keys(h.alternates).sort()).toEqual([...LANGS, 'x-default'].sort());
    // all of it is in the sitemap, so the canonical never contradicts the hreflang
    for (const u of [...h.canonical, ...Object.values(h.alternates)]) expect(locs).toContain(u);
    // a language address is its own canonical, and still lists the same alternates
    for (const l of LANGS) {
      await page.goto(`${p}?lang=${l}`);
      h = await head(page);
      expect(h.canonical, l).toEqual([`${SITE}${p}?lang=${l}`]);
      expect(Object.values(h.alternates), l).toContain(h.canonical[0]);
      expect(h.alternates[l]).toBe(h.canonical[0]);
      expect(await page.evaluate(() => document.documentElement.lang)).toBe(l);
    }
    // an unknown language, "auto", or a resort in testing keep the plain canonical
    for (const q of ['?lang=xx', '?lang=auto']) {
      await page.goto(p + q);
      expect((await head(page)).canonical, q).toEqual([SITE + p]);
    }
    expect(errors).toEqual([]);
  });
}

test('אתר סקי בבדיקה לא בחיפוש: robots, sitemap ו-canonical', async ({ page }) => {
  const robots = await (await page.request.get('/robots.txt')).text();
  expect(robots).toContain('Disallow: /*?resort=');
  expect(robots).toContain('Disallow: /*&resort=');
  expect(robots).toContain('Sitemap: ' + SITE + '/sitemap.xml');
  expect(await (await page.request.get('/sitemap.xml')).text()).not.toContain('resort=');
  await page.goto('/?resort=soelden&lang=en');
  expect((await head(page)).canonical).toEqual([SITE + '/']);
  // the head says nothing that would put it in the index either way: it is the robots.txt that keeps it out
  const hidden = JSON.parse(readFileSync('site/data/resorts.json', 'utf8')).resorts.filter((r: { hidden?: boolean }) => r.hidden);
  expect(hidden.length).toBeGreaterThan(0);
  for (const r of hidden) expect(sitemap).not.toContain(r.id);
});
